<?php
namespace App\Services;use App\Enums\CommitteeStatus;use App\Models\{Committee,CommitteeOperationalAudit};use Illuminate\Validation\ValidationException;
class CommitteeOperationService{public function ensureActive(Committee $committee):void{$committee->loadMissing('latestFinalFormation.period');if($committee->status!==CommitteeStatus::ACTIVE||!$committee->latestFinalFormation)throw ValidationException::withMessages(['committee'=>'Solo un comité conformado y activo puede usar las funciones operativas.']);$today=now()->startOfDay();if($today->lt($committee->latestFinalFormation->effective_from)||$today->gt($committee->latestFinalFormation->effective_to))throw ValidationException::withMessages(['committee'=>'El período activo del comité no está vigente.']);}public function audit(Committee $committee,string $event,$subject,?int $userId,array $metadata=[]):void{CommitteeOperationalAudit::create(['committee_id'=>$committee->id,'event'=>$event,'subject_type'=>is_object($subject)?$subject::class:null,'subject_id'=>is_object($subject)?$subject->id:null,'user_id'=>$userId,'metadata'=>$metadata,'created_at'=>now()]);}}
